import { Router } from "express";
import resumeController from "../controllers/resume.controller";
import resumeAIController from "../controllers/resume.controller";
import { protect, authorize } from "../middleware/authMiddleware";
import { validate } from "../middleware/validation.middleware";
import { createResumeValidation, updateResumeValidation, getResumeValidation, deleteResumeValidation, duplicateResumeValidation, setDefaultResumeValidation, downloadPDFValidation, exportResumeValidation, analyzeResumeValidation, generateCoverLetterValidation, careerFeedbackValidation, jobMatchesValidation, improvementSuggestionsValidation, bulkDeleteValidation, } from "../validations/resume.validator";
const router = Router();
router.get("/", protect, resumeController.getUserResumes);
router.post("/", protect, validate(createResumeValidation), resumeController.createResume);
router.get("/stats", protect, resumeController.getResumeStats);
router.post("/bulk-delete", protect, validate(bulkDeleteValidation), resumeController.bulkDeleteResumes);
router.get("/:id", protect, validate(getResumeValidation), resumeController.getResume);
router.put("/:id", protect, validate(updateResumeValidation), resumeController.updateResume);
router.delete("/:id", protect, validate(deleteResumeValidation), resumeController.deleteResume);
router.post("/:id/duplicate", protect, validate(duplicateResumeValidation), resumeController.duplicateResume);
router.put("/:id/default", protect, validate(setDefaultResumeValidation), resumeController.setDefaultResume);
router.get("/:id/pdf", protect, validate(downloadPDFValidation), resumeController.downloadResumePDF);
router.get("/:id/export", protect, validate(exportResumeValidation), resumeController.exportResume);
router.get("/:id/analyze", protect, validate(analyzeResumeValidation), resumeAIController.analyzeResume);
router.post("/:id/generate-cover-letter", protect, authorize("job-seeker"), validate(generateCoverLetterValidation), resumeAIController.generateCoverLetter);
router.get("/:id/career-feedback", protect, validate(careerFeedbackValidation), resumeAIController.getCareerFeedback);
router.get("/:id/job-matches", protect, validate(jobMatchesValidation), resumeAIController.getJobMatches);
router.get("/:id/improvements", protect, validate(improvementSuggestionsValidation), resumeAIController.getImprovementSuggestions);
export default router;
